from __future__ import annotations

from typing import Any

LOCAL_NOTE = (
    "\n\n*Running in local mode. Start an OpenAI-compatible model at "
    "`http://localhost:8001/v1` for full autonomous completions.*"
)

IDLE_REPLY = (
    'I heard: **"{user_input}"**.\n\n'
    "In The Living Studio every idea is judged against human outcomes instead of "
    "story points. Here is the landscape you are working in — the scores above 10 are "
    "the ones worth building." + LOCAL_NOTE
)

JOB_MAP_STEPS: list[dict[str, str]] = [
    {"name": "Define what success means", "stage": "define"},
    {"name": "Locate the inputs and the people", "stage": "locate"},
    {"name": "Prepare the environment", "stage": "prepare"},
    {"name": "Confirm it is safe to proceed", "stage": "confirm"},
    {"name": "Execute the change", "stage": "execute"},
    {"name": "Monitor for drift", "stage": "monitor"},
    {"name": "Modify when reality diverges", "stage": "modify"},
    {"name": "Conclude and hand off", "stage": "conclude"},
]


def guidelines_spec() -> dict[str, Any]:
    return {
        "type": "job-map",
        "props": {
            "job": "Keep every environment in sync with the truth",
            "steps": JOB_MAP_STEPS,
            "actions": [
                {
                    "label": "Score an outcome",
                    "intent": "Help me score a desired outcome with importance and satisfaction.",
                    "tone": "primary",
                }
            ],
        },
    }


def opportunity_spec() -> dict[str, Any]:
    return {
        "type": "opportunity-board",
        "props": {
            "title": "Where the market is underserved",
            "outcomes": [
                {
                    "id": "O-1",
                    "statement": "Minimize the time it takes to propagate secrets across environments",
                    "importance": 9,
                    "satisfaction": 3,
                },
                {
                    "id": "O-2",
                    "statement": "Minimize the likelihood of a failed deploy after a key rotation",
                    "importance": 8,
                    "satisfaction": 4,
                },
                {
                    "id": "O-3",
                    "statement": "Minimize the effort required to audit who changed a credential",
                    "importance": 6,
                    "satisfaction": 7,
                },
            ],
            "actions": [
                {
                    "label": "Simulate a bet",
                    "intent": "Simulate a zero-touch secret sync on outcome O-1.",
                    "tone": "primary",
                },
                {
                    "label": "Show customer evidence",
                    "intent": "Show me the customer evidence behind outcome O-1.",
                },
            ],
        },
    }


def simulation_spec() -> dict[str, Any]:
    return {
        "type": "impact-simulation",
        "props": {
            "outcome": {
                "id": "O-1",
                "statement": "Minimize the time it takes to propagate secrets across environments",
            },
            "bet": "A zero-touch secret sync daemon that follows the deploy, not the calendar",
            "before": [
                "45 minutes of copy-paste per rotation",
                "14% of deploys fail on configuration drift",
                "400 teams carry the same manual ritual",
            ],
            "after": [
                "Under 30 seconds, ambient and unattended",
                "Zero human steps in the happy path",
                "3,000 engineer-hours returned every month",
            ],
            "metrics": [
                {"label": "Time to value", "value": "-90%", "delta": "Friction removed"},
                {"label": "Satisfaction", "value": "8.9 / 10", "delta": "+5.8 points"},
                {"label": "Risk", "value": "Low", "delta": "Non-breaking"},
            ],
            "verdict": "Build it. The friction is measurable, recurring, and entirely avoidable.",
            "actions": [
                {
                    "label": "Write the decision record",
                    "intent": "Draft a Product Decision Record for the zero-touch secret sync bet.",
                    "tone": "primary",
                }
            ],
        },
    }


def evidence_spec() -> dict[str, Any]:
    return {
        "type": "evidence-quote",
        "props": {
            "source": "Gong call #104 — FinTech Corp",
            "quote": (
                "A junior engineer pushed code that failed staging because the Stripe "
                "secret wasn't copied over. It took three seniors two hours to find "
                "out why the cluster wouldn't start. There has to be a better way "
                "than copy-pasting strings."
            ),
            "linkedTo": "JOB-402 / O-1",
            "severity": "high",
            "actions": [
                {
                    "label": "Score this outcome",
                    "intent": "Score outcome O-1 using the evidence from call #104.",
                    "tone": "primary",
                }
            ],
        },
    }


def offline_reply(user_input: str) -> tuple[str, list[dict[str, Any]]]:
    """Return prose plus the surfaces that carry the evidence better than words."""
    lower = user_input.lower()

    if any(term in lower for term in ("guideline", "framework", "stage")):
        return (
            "Outcome-Driven Innovation moves in five moves. Here is the job, mapped "
            "to the eight universal stages, so you can see where the friction lives.",
            [guidelines_spec()],
        )

    if any(term in lower for term in ("simulate", "bet", "impact")):
        return (
            "Simulated against the highest-opportunity outcome. The bet is worth "
            "making; the numbers below are where the value comes from.",
            [simulation_spec()],
        )

    if any(term in lower for term in ("evidence", "call", "quote", "research")):
        return (
            "Here is the customer voice behind the score. Link evidence to the "
            "outcome before you argue about solutions.",
            [evidence_spec()],
        )

    return (IDLE_REPLY.format(user_input=user_input), [opportunity_spec()])


__all__ = [
    "IDLE_REPLY",
    "JOB_MAP_STEPS",
    "LOCAL_NOTE",
    "evidence_spec",
    "guidelines_spec",
    "offline_reply",
    "opportunity_spec",
    "simulation_spec",
]
