/**
 * A turn is an ordered sequence of parts, so a card can sit between two
 * paragraphs exactly where the agent put it. `content` stays as the combined
 * prose because that is what gets replayed as conversation history.
 */
export type ChatPart =
  | { kind: "text"; text: string }
  | { kind: "ui"; id: string; node: UiNode };

