:root {
  color-scheme: dark;
  --studio-bg-1: #131722;
  --studio-bg-2: #0b0d13;
  --studio-text: #f1f5f9;
  --studio-muted: #94a3b8;
  --studio-indigo: #818cf8;
  --studio-indigo-strong: #6366f1;
  --studio-green: #34d399;
  --studio-amber: #fbbf24;
  --studio-red: #f87171;
  --studio-surface: rgba(255, 255, 255, 0.03);
  --studio-surface-strong: rgba(255, 255, 255, 0.05);
  --studio-border: rgba(255, 255, 255, 0.08);
  --studio-radius: 12px;
  --studio-font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial,
    sans-serif;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  font-family: var(--studio-font);
}

.studio-app {
  min-height: 100vh;
  padding: 16px 20px 32px;
  background: radial-gradient(circle at 15% 15%, var(--studio-bg-1) 0%, var(--studio-bg-2) 100%);
  color: var(--studio-text);
  font-family: var(--studio-font);
}

/* ------------------------------------------------------------------ */
/* Header + status pills                                              */
/* ------------------------------------------------------------------ */
.studio-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 18px;
  background: var(--studio-surface);
  border: 1px solid var(--studio-border);
  border-radius: var(--studio-radius);
  margin-bottom: 18px;
  gap: 16px;
  flex-wrap: wrap;
}

.studio-header__title {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.studio-header__title span {
  opacity: 0.5;
  font-size: 1rem;
  font-weight: 400;
}

.studio-header__subtitle {
  font-size: 0.85rem;
  color: var(--studio-muted);
  margin-top: 2px;
}

.studio-header__pills {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.studio-pill {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 9999px;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  white-space: nowrap;
}

.pill-green {
  background: rgba(16, 185, 129, 0.15);
  color: var(--studio-green);
  border: 1px solid rgba(16, 185, 129, 0.3);
}

.pill-amber {
  background: rgba(245, 158, 11, 0.15);
  color: var(--studio-amber);
  border: 1px solid rgba(245, 158, 11, 0.3);
}

.pill-blue {
  background: rgba(99, 102, 241, 0.15);
  color: var(--studio-indigo);
  border: 1px solid rgba(99, 102, 241, 0.3);
}

.studio-icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 9px;
  border: 1px solid var(--studio-border);
  background: var(--studio-surface);
  color: var(--studio-muted);
  cursor: pointer;
  transition:
    color 0.15s ease,
    border-color 0.15s ease,
    background 0.15s ease;
}

.studio-icon-button:hover,
.studio-icon-button[aria-expanded="true"] {
  color: var(--studio-text);
  border-color: rgba(129, 140, 248, 0.45);
  background: rgba(129, 140, 248, 0.08);
}

/* ------------------------------------------------------------------ */
/* Layout: canvas + chat                                              */
/* ------------------------------------------------------------------ */
.studio-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 24px;
  align-items: start;
}

@media (max-width: 1024px) {
  .studio-layout {
    grid-template-columns: 1fr;
  }
}

/* ------------------------------------------------------------------ */
/* Outcome cards                                                      */
/* ------------------------------------------------------------------ */
.outcome-card {
  padding: 14px 18px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.025);
  border: 1px solid var(--studio-border);
  margin-bottom: 12px;
  transition: all 0.2s ease-in-out;
}

.outcome-card:hover {
  border-color: rgba(99, 102, 241, 0.4);
  background: rgba(255, 255, 255, 0.04);
}

.pulsing-card {
  border-left: 4px solid #f59e0b !important;
  box-shadow: 0 0 14px rgba(245, 158, 11, 0.18);
}

.outcome-card__head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
}

.outcome-card__id {
  font-weight: 700;
  color: var(--studio-indigo);
}

.outcome-card__statement {
  font-size: 1rem;
  font-weight: 500;
  margin: 8px 0;
}

.outcome-card__meta {
  font-size: 0.82rem;
  color: var(--studio-muted);
}

.outcome-card__actions {
  display: grid;
  grid-template-columns: 0.33fr 0.33fr 0.34fr;

