    if (!activeGoal) {
      return;
    }
    complete();
    setActiveTab(activeGoal.tab);
    revealCanvas();
    void sendMessage(activeGoal.prompt);
  }

  function openCanvas() {
    if (activeGoal) {
      setActiveTab(activeGoal.tab);
    }
    complete();
    revealCanvas();
  }

  if (!enabled || !open) {
    return null;
  }

