   gap: 4px;
   flex-wrap: wrap;
   border-bottom: 1px solid var(--studio-border);
   margin-bottom: 16px;
 }

 .studio-tab {
   background: transparent;
   border: none;
   color: var(--studio-muted);
   padding: 8px 12px;
   border-radius: 8px 8px 0 0;
   cursor: pointer;
   font-size: 0.88rem;
   font-family: inherit;
 }

 .studio-tab[aria-selected="true"] {
   color: var(--studio-text);
   background: var(--studio-surface);
   border-bottom: 2px solid var(--studio-indigo-strong);
 }

 .studio-tab:hover {
   color: var(--studio-text);
 }

 .studio-card {
   padding: 14px 16px;
   border-radius: 10px;
   background: var(--studio-surface);
   border: 1px solid var(--studio-border);
   margin-bottom: 12px;
 }

 .step-row {
   padding: 10px 14px;
   background: var(--studio-surface);
   border-radius: 8px;
   margin-bottom: 8px;
   border-left: 3px solid var(--studio-indigo-strong);
 }

 .section-title {
   margin: 0 0 4px;
   font-size: 1.05rem;
 }

 .caption {
   color: var(--studio-muted);
   font-size: 0.82rem;
   margin: 0 0 14px;
 }

 /* Buttons + inputs */
 button,
 input,
 select,
 textarea {
   font-family: inherit;
 }

 .studio-button {
   background: rgba(99, 102, 241, 0.16);
   color: var(--studio-text);
   border: 1px solid rgba(99, 102, 241, 0.35);
   border-radius: 8px;
   padding: 8px 12px;
   cursor: pointer;
   font-size: 0.85rem;
   transition: background 0.15s ease;
 }

 .studio-button:hover {
   background: rgba(99, 102, 241, 0.28);
 }

 .studio-button:disabled {
   opacity: 0.55;
   cursor: not-allowed;
 }

 .studio-button--ghost {
   background: transparent;
   border-color: var(--studio-border);
 }

 .studio-input,
 .studio-select {
   width: 100%;
   background: rgba(15, 23, 42, 0.6);
   border: 1px solid var(--studio-border);
   border-radius: 8px;
   color: var(--studio-text);
   padding: 8px 10px;
   font-size: 0.88rem;
 }

 .studio-field {
   margin-bottom: 12px;
 }

 .studio-field label {
   display: block;
   font-size: 0.8rem;
   color: var(--studio-muted);
   margin-bottom: 4px;
 }

 input[type="range"] {
   width: 100%;
 }

 .studio-form-grid {
   display: grid;
   grid-template-columns: 1fr 1fr;
   gap: 12px;
 }

 /* ------------------------------------------------------------------ */
 /* Chat copilot                                                       */
 /* ------------------------------------------------------------------ */
 .chat-copilot {
   position: sticky;
   top: 16px;
 }

 .chat-copilot__head {
   display: flex;
   align-items: baseline;
   justify-content: space-between;
   gap: 12px;
   margin-bottom: 10px;
 }

 .chat-copilot__title {
   margin: 0;
   font-size: 1.02rem;
   letter-spacing: -0.01em;
 }

 .chat-copilot__caption {
   margin: 0;
   text-align: right;
 }

 .chat-log {
   height: min(64vh, 640px);
   overflow-y: auto;
   padding: 4px 14px 18px 2px;
   display: flex;
   flex-direction: column;
   gap: 18px;
   scroll-behavior: smooth;
 }

 .chat-turn {
   display: flex;
   flex-direction: column;
   gap: 10px;
   min-width: 0;
 }

 .chat-turn--assistant {
   align-self: stretch;
 }

 .chat-turn--user {
   align-self: flex-end;
   max-width: 86%;
   align-items: flex-end;
 }

 .chat-turn--user .chat-turn__text {
   background: rgba(99, 102, 241, 0.16);
   border: 1px solid rgba(99, 102, 241, 0.3);
   border-radius: 14px 14px 4px 14px;
   padding: 9px 13px;
   font-size: 0.9rem;
 }

 .chat-turn--user .ui-richtext__paragraph {
   margin: 0;
 }

 .chat-turn--assistant .chat-turn__text {
   font-size: 0.93rem;
   line-height: 1.6;
   color: #e2e8f0;
 }

 .chat-turn__text {
   word-break: break-word;
 }

 .chat-input-row {
   display: flex;
   gap: 8px;
   margin-top: 10px;
   align-items: flex-end;
 }

 .chat-quick-pills {
   display: flex;
   flex-wrap: wrap;
   gap: 6px;
   margin-bottom: 10px;
 }

 .chat-quick-pill {
   background: transparent;
   border: 1px solid var(--studio-border);
   color: var(--studio-muted);
   border-radius: 9999px;
   padding: 5px 11px;
   font-size: 0.78rem;
   cursor: pointer;
   transition: color 0.15s ease, border-color 0.15s ease, background 0.15s ease;
 }

 .chat-quick-pill:hover {
   color: var(--studio-text);
   border-color: rgba(129, 140, 248, 0.45);
   background: rgba(129, 140, 248, 0.08);
 }

 .chat-quick-pill:disabled {
   opacity: 0.5;
   cursor: not-allowed;
 }

 /* Tool activity reads as status, not output. */
 .chat-activity {
   display: flex;
   flex-wrap: wrap;
   gap: 6px;
   padding-left: 2px;
 }

 .chat-activity__chip {
   display: inline-flex;
   align-items: center;
   gap: 5px;
   padding: 3px 8px;
   border-radius: 6px;
   border: 1px solid var(--studio-border);
   background: rgba(148, 163, 184, 0.06);
   font-size: 0.72rem;
   color: var(--studio-muted);
   font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
 }

 .chat-activity__chip--ok .chat-activity__mark {
   color: var(--studio-green);
 }

 .chat-activity__chip--error {
   border-color: rgba(248, 113, 113, 0.4);
   color: var(--studio-red);
 }

 .chat-thinking {
   display: inline-flex;
   align-items: center;
   gap: 5px;
   color: var(--studio-muted);
   font-size: 0.82rem;
   padding: 2px 4px;
 }

 .chat-thinking__dot {
   width: 5px;
   height: 5px;
   border-radius: 50%;
   background: var(--studio-indigo);
   animation: thinking-pulse 1.1s infinite ease-in-out;
 }

 .chat-thinking__dot:nth-child(2) {
   animation-delay: 0.15s;
 }

 .chat-thinking__dot:nth-child(3) {
   animation-delay: 0.3s;
 }

 .chat-thinking__label {
   margin-left: 6px;
 }

 @keyframes thinking-pulse {
   0%,
   80%,
   100% {
     opacity: 0.25;
     transform: scale(0.85);
   }

   40% {
     opacity: 1;
     transform: scale(1);
   }
 }

 /* ------------------------------------------------------------------ */
 /* Rich text                                                          */
 /* ------------------------------------------------------------------ */
 .ui-richtext__paragraph {
   margin: 0 0 8px;
 }

 .ui-richtext__paragraph:last-child {
   margin-bottom: 0;
 }

 .ui-richtext__heading {
   margin: 2px 0 8px;
   font-size: 0.95rem;
   letter-spacing: 0.01em;
 }

 .ui-richtext__list {
   margin: 0 0 8px;
   padding-left: 18px;
 }

 .ui-richtext__list li {
   margin-bottom: 4px;
 }

 .ui-code {
   font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
   font-size: 0.86em;
   background: rgba(148, 163, 184, 0.14);
   padding: 1px 5px;
   border-radius: 4px;
 }

 /* ------------------------------------------------------------------ */
 /* Generated surfaces                                                 */
 /* ------------------------------------------------------------------ */
 .ui-surface {
   animation: surface-enter 0.28s cubic-bezier(0.16, 1, 0.3, 1) both;
   min-width: 0;
 }

 @keyframes surface-enter {
   from {
     opacity: 0;
     transform: translateY(6px);
   }

   to {
     opacity: 1;
     transform: none;
   }
 }

 .ui-stack {
   display: flex;
   flex-direction: column;
   min-width: 0;
 }

 .ui-stack--horizontal {
   flex-direction: row;
   flex-wrap: wrap;
   align-items: center;
   justify-content: flex-start;
 }

 .ui-grid {
   display: grid;
   min-width: 0;
 }

 .ui-grid--2 {
   grid-template-columns: repeat(2, minmax(0, 1fr));
 }

 .ui-grid--3 {
   grid-template-columns: repeat(3, minmax(0, 1fr));
 }

 .ui-gap--sm {
   gap: 8px;
 }

 .ui-gap--md {
   gap: 12px;
 }

 .ui-gap--lg {
   gap: 18px;
 }

 .ui-heading {
   margin: 0;
   font-size: 0.95rem;
 }

 .ui-text {
   font-size: 0.92rem;
   line-height: 1.55;
 }

 .ui-text--muted {
   color: var(--studio-muted);
 }

 .ui-text--positive {
   color: var(--studio-green);
 }

 .ui-text--warning {
   color: var(--studio-amber);
 }

 .ui-text--critical {
   color: var(--studio-red);
 }

 .ui-caption {
   margin: 0;
   font-size: 0.72rem;
   letter-spacing: 0.06em;
   text-transform: uppercase;
   color: var(--studio-muted);
 }

 /* Cards */
 .ui-card {
   display: flex;
   flex-direction: column;
   gap: 12px;
   padding: 16px 18px;
   border-radius: 14px;
   border: 1px solid var(--studio-border);
   background: linear-gradient(180deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0.015));
   box-shadow: 0 1px 0 rgba(255, 255, 255, 0.04) inset, 0 12px 30px -26px rgba(0, 0, 0, 0.9);
   min-width: 0;
 }

 .ui-card--urgent {
   border-color: rgba(251, 191, 36, 0.28);
   box-shadow: 0 0 0 1px rgba(251, 191, 36, 0.05), 0 18px 44px -30px rgba(251, 191, 36, 0.45);
 }

 .ui-card--unknown {
   background: transparent;
   border-style: dashed;
   gap: 4px;
 }

 .ui-card__head {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 10px;
 }

 .ui-card__id {
   font-size: 0.72rem;
   font-weight: 700;
   letter-spacing: 0.09em;
   text-transform: uppercase;
   color: var(--studio-indigo);
 }

 .ui-card__statement {
   margin: 0;
   font-size: 0.98rem;
   font-weight: 500;
   line-height: 1.45;
 }

 .ui-card__title {
   margin: 0;
   font-size: 1rem;
 }

 .ui-card__formula {
   margin: 0;
   font-size: 0.72rem;
   color: var(--studio-muted);
   font-variant-numeric: tabular-nums;
 }

 .ui-card__meters {
   display: grid;
   gap: 8px;
 }

 .ui-card__evidence {
   margin: 0;
   padding: 10px 12px;
   border-left: 2px solid rgba(129, 140, 248, 0.5);
   background: rgba(15, 23, 42, 0.5);
   border-radius: 0 8px 8px 0;
   font-size: 0.84rem;
   color: #cbd5e1;
 }

 /* Pills */
 .ui-pill {
   display: inline-flex;
   align-items: center;
   padding: 3px 9px;
   border-radius: 9999px;
   border: 1px solid transparent;
   font-size: 0.72rem;
   font-weight: 600;
   white-space: nowrap;
   font-variant-numeric: tabular-nums;
 }

 .ui-pill--neutral {
   background: rgba(148, 163, 184, 0.12);
   border-color: rgba(148, 163, 184, 0.22);
   color: #cbd5e1;
 }

 .ui-pill--positive {
   background: rgba(52, 211, 153, 0.12);
   border-color: rgba(52, 211, 153, 0.28);
   color: var(--studio-green);
 }

 .ui-pill--warning {
   background: rgba(251, 191, 36, 0.12);
   border-color: rgba(251, 191, 36, 0.3);
   color: var(--studio-amber);
 }

 .ui-pill--critical {
   background: rgba(248, 113, 113, 0.12);
   border-color: rgba(248, 113, 113, 0.3);
   color: var(--studio-red);
 }

 .ui-pill--info {
   background: rgba(129, 140, 248, 0.12);
   border-color: rgba(129, 140, 248, 0.3);
   color: var(--studio-indigo);
 }

 /* Meters */
 .ui-meter__head {
   display: flex;
   justify-content: space-between;
   font-size: 0.74rem;
   color: var(--studio-muted);
   margin-bottom: 4px;
 }

 .ui-meter__value {
   color: #cbd5e1;
   font-variant-numeric: tabular-nums;
 }

 .ui-meter__track {
   height: 5px;
   border-radius: 9999px;
   background: rgba(148, 163, 184, 0.14);
   overflow: hidden;
 }

 .ui-meter__fill {
   display: block;
   height: 100%;
   border-radius: 9999px;
   transition: width 0.4s cubic-bezier(0.16, 1, 0.3, 1);
 }

 .ui-tone-bg--neutral {
   background: #94a3b8;
 }

 .ui-tone-bg--positive {
   background: var(--studio-green);
 }

 .ui-tone-bg--warning {
   background: var(--studio-amber);
 }

 .ui-tone-bg--critical {
   background: var(--studio-red);
 }

 .ui-tone-bg--info {
   background: var(--studio-indigo);
 }

 /* Stats */
 .ui-stat {
   padding: 10px 12px;
   border-radius: 10px;
   border: 1px solid var(--studio-border);
   background: rgba(15, 23, 42, 0.5);
   min-width: 0;
 }

 .ui-stat__label {
   font-size: 0.68rem;
   letter-spacing: 0.07em;
   text-transform: uppercase;
   color: var(--studio-muted);
 }

 .ui-stat__value {
   margin-top: 3px;
   font-size: 1.15rem;
   font-weight: 700;
   font-variant-numeric: tabular-nums;
 }

 .ui-stat__delta {
   font-size: 0.72rem;
   color: var(--studio-muted);
 }

 .ui-stat.ui-tone--positive .ui-stat__value {
   color: var(--studio-green);
 }

 .ui-stat.ui-tone--warning .ui-stat__value {
   color: var(--studio-amber);
 }

 .ui-stat.ui-tone--critical .ui-stat__value {
   color: var(--studio-red);
 }

 /* Callouts */
 .ui-callout {
   display: flex;
   flex-direction: column;
   gap: 4px;
   padding: 11px 13px;
   border-radius: 10px;
   border: 1px solid;
   border-left-width: 3px;
   font-size: 0.85rem;
 }

 .ui-callout--info {
   background: rgba(129, 140, 248, 0.07);
   border-color: rgba(129, 140, 248, 0.25);
 }

 .ui-callout--positive {
   background: rgba(52, 211, 153, 0.07);
   border-color: rgba(52, 211, 153, 0.25);
 }

 .ui-callout--warning {
   background: rgba(251, 191, 36, 0.07);
   border-color: rgba(251, 191, 36, 0.25);
 }

 .ui-callout--critical {
   background: rgba(248, 113, 113, 0.07);
   border-color: rgba(248, 113, 113, 0.25);
 }

 .ui-callout__title {
   font-size: 0.8rem;
   font-weight: 600;
 }

 /* Lists + divider */
 .ui-list {
   margin: 0;
   padding-left: 18px;
   display: flex;
   flex-direction: column;
   gap: 4px;
   font-size: 0.88rem;
 }

 .ui-list--check {
   list-style: none;
   padding-left: 2px;
 }

 .ui-list--check li::before {
   content: "✓";
   color: var(--studio-green);
   margin-right: 7px;
   font-size: 0.8em;
 }

 .ui-divider {
   border: none;
   border-top: 1px solid var(--studio-border);
   margin: 2px 0;
   width: 100%;
 }

 /* Actions */
 .ui-actions {
   display: flex;
   flex-wrap: wrap;
   gap: 8px;
 }

 .ui-action {
   border: 1px solid transparent;
   border-radius: 8px;
   padding: 7px 12px;
   font-size: 0.82rem;
   font-weight: 500;
   cursor: pointer;
   transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease,
     transform 0.1s ease;
 }

 .ui-action--primary {
   background: var(--studio-indigo-strong);
   border-color: rgba(255, 255, 255, 0.08);
   color: #fff;
 }

 .ui-action--primary:hover {
   background: #7c7ff5;
 }

 .ui-action--ghost {
   background: transparent;
   border-color: var(--studio-border);
   color: #cbd5e1;
 }

 .ui-action--ghost:hover {
   border-color: rgba(129, 140, 248, 0.45);
   color: var(--studio-text);
 }

 .ui-action:active {
   transform: translateY(1px);
 }

 .ui-action:disabled {
   opacity: 0.5;
   cursor: not-allowed;
   transform: none;
 }

 /* Tables */
 .ui-table-wrap {
   overflow-x: auto;
 }

 .ui-table {
   width: 100%;
   border-collapse: collapse;
   font-size: 0.86rem;
 }

 .ui-table th {
   padding: 0 0 6px;
   border-bottom: 1px solid var(--studio-border);
   text-align: left;
   font-size: 0.66rem;
   font-weight: 600;
   letter-spacing: 0.08em;
   text-transform: uppercase;
   color: var(--studio-muted);
 }

 .ui-table td {
   padding: 9px 0;
   border-bottom: 1px solid rgba(255, 255, 255, 0.04);
   vertical-align: top;
 }

 .ui-table tr:last-child td {
   border-bottom: none;
 }

 .ui-table td:first-child {
   padding-right: 12px;
 }

 .ui-table td:last-child {
   text-align: right;
   white-space: nowrap;
 }

 .ui-table .ui-card__id {
   display: block;
 }

 .ui-table__statement {
   display: block;
   margin-top: 3px;
   line-height: 1.4;
   color: #cbd5e1;
 }

 .ui-table__row--urgent .ui-card__id {
   color: var(--studio-amber);
 }

 /* Impact simulation */
 .ui-bet {
   display: flex;
   align-items: baseline;
   gap: 8px;
   padding: 9px 12px;
   border-radius: 8px;
   border: 1px solid rgba(129, 140, 248, 0.2);
   background: rgba(129, 140, 248, 0.07);
 }

 .ui-bet__label {
   font-size: 0.64rem;
   letter-spacing: 0.08em;
   text-transform: uppercase;
   color: var(--studio-indigo);
   white-space: nowrap;
 }

 .ui-bet__value {
   font-size: 0.88rem;
   color: #e2e8f0;
 }

 .ui-phase {
   padding: 12px;
   border-radius: 10px;
   border: 1px solid;
   min-width: 0;
 }

 .ui-phase.ui-tone--critical {
   background: rgba(248, 113, 113, 0.06);
   border-color: rgba(248, 113, 113, 0.22);
 }

 .ui-phase.ui-tone--positive {
   background: rgba(52, 211, 153, 0.06);
   border-color: rgba(52, 211, 153, 0.22);
 }

 .ui-phase__label {
   margin-bottom: 7px;
   font-size: 0.64rem;
   letter-spacing: 0.09em;
   text-transform: uppercase;
   color: var(--studio-muted);
 }

 .ui-phase__items {
   margin: 0;
   padding-left: 16px;
   display: flex;
   flex-direction: column;
   gap: 5px;
   font-size: 0.84rem;
   color: #cbd5e1;
 }

 /* Evidence */
 .ui-quote {
   margin: 0;
   padding-left: 12px;
   border-left: 2px solid rgba(129, 140, 248, 0.5);
   font-size: 0.95rem;
   font-style: italic;
   line-height: 1.55;
   color: #e2e8f0;
 }

 /* Job map */
 .ui-jobmap {
   list-style: none;
   margin: 0;
   padding: 0;
 }

 .ui-jobmap__step {
   display: flex;
   gap: 10px;
   padding: 8px 0;
   border-bottom: 1px solid rgba(255, 255, 255, 0.04);
 }

 .ui-jobmap__step:last-child {
   border-bottom: none;
 }

 .ui-jobmap__index {
   flex: none;
   display: grid;
   place-items: center;
   width: 20px;
   height: 20px;
   border-radius: 6px;
   background: rgba(129, 140, 248, 0.14);
   color: var(--studio-indigo);
   font-size: 0.7rem;
   font-weight: 700;
   font-variant-numeric: tabular-nums;
 }

 .ui-jobmap__body {
   display: flex;
   flex-direction: column;
   gap: 2px;
 }

 .ui-jobmap__name {
   font-size: 0.88rem;
 }

 .ui-jobmap__stage {
   font-size: 0.64rem;
   letter-spacing: 0.08em;
   text-transform: uppercase;
   color: var(--studio-muted);
 }

 .ui-jobmap__note {
   font-size: 0.78rem;
   color: var(--studio-muted);
 }

 /* Decision record */
 .ui-fields {
   margin: 0;
   display: flex;
   flex-direction: column;
   gap: 10px;
 }

 .ui-field {
   display: flex;
   flex-direction: column;
   gap: 2px;
 }

 .ui-field dt {
   font-size: 0.64rem;
   letter-spacing: 0.08em;
   text-transform: uppercase;
   color: var(--studio-muted);
 }

 .ui-field dd {
   margin: 0;
   font-size: 0.88rem;
   color: #e2e8f0;
 }

 @media (max-width: 640px) {
   .ui-grid--2,
   .ui-grid--3 {
     grid-template-columns: minmax(0, 1fr);
   }

   .studio-icon-button {
     width: 44px;
     height: 44px;
   }
 }

 @media (prefers-reduced-motion: reduce) {
   .ui-surface,
   .fade-in {
     animation: none;
   }

   .ui-meter__fill,
   .chat-log {
     transition: none;
     scroll-behavior: auto;
   }

   .chat-thinking__dot {
     animation: none;
     opacity: 0.6;
   }
 }

 /* ------------------------------------------------------------------ */
 /* Toasts                                                             */
 /* ------------------------------------------------------------------ */
 .toast-stack {
   position: fixed;
   right: 20px;
   bottom: 20px;
   display: flex;
   flex-direction: column;
   gap: 8px;
   z-index: 1000;
   max-width: 360px;
 }

 .toast {
   padding: 10px 14px;
   border-radius: 8px;
   font-size: 0.85rem;
   background: rgba(15, 23, 42, 0.95);
   border: 1px solid var(--studio-border);
   box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
 }

 .toast--success {
   border-color: rgba(16, 185, 129, 0.5);
   color: var(--studio-green);
 }

 .toast--error {
   border-color: rgba(239, 68, 68, 0.5);
   color: var(--studio-red);
 }

 .toast--info {
   border-color: rgba(99, 102, 241, 0.5);
   color: var(--studio-indigo);
 }

 /* ------------------------------------------------------------------ */
 /* Settings drawer + badges                                           */
 /* ------------------------------------------------------------------ */
 .settings-drawer {
   background: var(--studio-surface);
   border: 1px solid var(--studio-border);
   border-radius: 10px;
   padding: 14px 16px;
