export async function fetchMemory(): Promise<Observation[]> {
  const body = await getJson<{ observations: Observation[] }>("/api/memory");
  return body.observations;
}

export async function createObservation(
  payload: ObservationCreatePayload,
): Promise<Observation> {
  const body = await postJson<{ observation: Observation }>(
    "/api/memory/observations",
    payload,
  );
  return body.observation;
}

export async function updateObservation(
  observationId: string,
  payload: ObservationUpdatePayload,
): Promise<Observation> {
  const body = await patchJson<{ observation: Observation }>(
    `/api/memory/observations/${encodeURIComponent(observationId)}`,
    payload,
  );
  return body.observation;
}

export function clearMemory(): Promise<{ ok: boolean }> {
  return deleteJson<{ ok: boolean }>("/api/memory");
}

export async function fetchLatestConversation(): Promise<StoredConversation | null> {
  const body = await getJson<{ conversation: StoredConversation | null }>(
    "/api/conversations/latest",
  );
  return body.conversation;
}

export async function createConversation(): Promise<StoredConversation> {
  const body = await postJson<{ conversation: StoredConversation }>(
    "/api/conversations",
  );
  return body.conversation;
}

export type ChatEventHandler = (event: RawSseEvent) => void;

