import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { ONBOARDING_STORAGE_KEY } from "./storage";

const studio = vi.hoisted(() => ({
  settings: {
    base_url: "http://localhost:8001/v1",
    api_key: "local",
    model_name: "local-tools-model",
    mcp_url: "http://localhost:8000/mcp",
  },
  saveSettings: vi.fn(),
  sidecarReachable: true as boolean | null,
  mcpReachable: true as boolean | null,
  llmHealth: { healthy: true as boolean | null, message: "ok" },
  checkConnections: vi.fn(),
  sendMessage: vi.fn(async () => undefined),
  setActiveTab: vi.fn(),
  setEngagementLevel: vi.fn(),
  engagementLevel: 0,
}));

vi.mock("../state/StudioContext", () => ({
  useStudio: () => studio,
}));

import { FirstRunWizard } from "./FirstRunWizard";
import { OnboardingProvider } from "./OnboardingProvider";
import { useOnboarding } from "./context";

function renderWizard(enabled = true) {
  return render(
    <OnboardingProvider enabled={enabled}>
      <FirstRunWizard />
    </OnboardingProvider>,
  );
}

function seed(record: Record<string, unknown>) {
  window.localStorage.setItem(ONBOARDING_STORAGE_KEY, JSON.stringify(record));
}

function stored() {
  const raw = window.localStorage.getItem(ONBOARDING_STORAGE_KEY);
  return raw ? (JSON.parse(raw) as Record<string, unknown>) : null;
}

function continueButton() {
  return screen.getByRole("button", { name: "Continue" });
}

describe("FirstRunWizard", () => {
  beforeEach(() => {
    window.localStorage.clear();
    studio.sidecarReachable = true;
    studio.mcpReachable = true;
    studio.llmHealth = { healthy: true, message: "ok" };
    studio.engagementLevel = 0;
    studio.saveSettings.mockClear();
    studio.checkConnections.mockReset();
    studio.checkConnections.mockResolvedValue({
      sidecarReachable: true,
      mcpReachable: true,
      llmHealthy: true,
    });
    studio.sendMessage.mockClear();
    studio.setActiveTab.mockClear();
    studio.setEngagementLevel.mockClear();
  });

  it("greets a first-time user and focuses the step heading", () => {
    renderWizard();

    expect(screen.getByRole("dialog")).toHaveAttribute("aria-modal", "true");
    const heading = screen.getByRole("heading", { level: 2 });
    expect(heading).toHaveTextContent("People don't buy products.");
    expect(heading).toHaveFocus();
  });

  it("walks from a goal to a real first message", async () => {
    renderWizard();

    fireEvent.click(continueButton());
    expect(screen.getByRole("heading", { level: 2 })).toHaveTextContent(
      "Where do you want to begin?",
    );
    expect(continueButton()).toBeDisabled();

    fireEvent.click(screen.getByRole("button", { name: /Score the outcomes/ }));
    expect(continueButton()).toBeEnabled();
    fireEvent.click(continueButton());

    expect(screen.getByRole("heading", { level: 2 })).toHaveTextContent(
      "A quick look at your instruments.",
    );
    fireEvent.click(continueButton());

    expect(screen.getByRole("heading", { level: 2 })).toHaveTextContent(
      "Make your first move.",
    );
    expect(screen.getByText(/Help me capture and score a desired outcome/)).toBeInTheDocument();

    fireEvent.click(screen.getByRole("button", { name: "Send to the copilot" }));

    await waitFor(() => expect(screen.queryByRole("dialog")).not.toBeInTheDocument());
    expect(studio.sendMessage).toHaveBeenCalledWith(
      expect.stringContaining("Help me capture and score a desired outcome"),
    );
    expect(studio.setActiveTab).toHaveBeenCalledWith("landscape");
    expect(studio.setEngagementLevel).toHaveBeenCalledWith(1);
    expect(stored()).toMatchObject({
      status: "done",
      step: 3,
      goal: "score-outcomes",
      version: 1,
    });
  });

  it("can reveal the canvas instead of sending", () => {
    renderWizard();

    fireEvent.click(continueButton());
    fireEvent.click(screen.getByRole("button", { name: /Define the job/ }));
    fireEvent.click(continueButton());
    fireEvent.click(continueButton());
    fireEvent.click(screen.getByRole("button", { name: "Open the canvas" }));

    expect(studio.sendMessage).not.toHaveBeenCalled();
