          <p className="caption">
            <strong>Target URL:</strong> <code>{settings.base_url}</code>
            <br />
            <strong>Target Model:</strong> <code>{settings.model_name}</code>
            <br />
            <strong>MCP Bridge:</strong> <code>{settings.mcp_url}</code>
