    sans-serif;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  font-family: var(--studio-font);
}

.studio-app {
  min-height: 100vh;
  padding: 16px 20px 32px;
