  justify-content: space-between;
  gap: 12px;
}

.memory-panel__group {
  margin-bottom: 18px;
}

.memory-panel__kind {
  margin: 0 0 8px;
  font-size: 0.76rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--studio-muted);
}

.memory-panel__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.memory-item {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  padding: 12px 14px;
  border: 1px solid var(--studio-border);
  border-radius: 10px;
  background: var(--studio-surface);
}

.memory-item__body {
  min-width: 0;
  flex: 1;
}

.memory-item__text {
  margin: 0 0 6px;
  font-size: 0.9rem;
  line-height: 1.45;
}

.memory-item__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  font-size: 0.72rem;
  color: var(--studio-muted);
}

.memory-item__status--suggested {
  color: var(--studio-amber);
}

.memory-item__status--confirmed {
  color: var(--studio-green);
}

.memory-item__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: flex-end;
}

.memory-item__actions .studio-button {
  padding: 5px 9px;
  font-size: 0.76rem;
}

.memory-item__edit {
  min-height: 64px;
  margin-bottom: 6px;
  resize: vertical;
}

.memory-panel__empty {
  margin-bottom: 18px;
}

.memory-panel__empty p {
  margin: 0 0 6px;
}

.memory-panel__add-row {
  display: grid;
  grid-template-columns: minmax(130px, 0.7fr) minmax(0, 2fr) auto;
  gap: 8px;
  align-items: center;
}

.memory-panel__danger {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 6px;
  font-size: 0.8rem;
  color: var(--studio-muted);
}

@media (max-width: 760px) {
  .memory-item {
    flex-direction: column;
  }

  .memory-item__actions {
    justify-content: flex-start;
  }

  .memory-panel__add-row {
    grid-template-columns: minmax(0, 1fr);
  }
}
EOF

