import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";

import type { Observation } from "../../types";
import { MemoryPanel } from "./MemoryPanel";

const studio = vi.hoisted(() => ({
  memory: [] as Observation[],
  memoryLoading: false,
  refreshMemory: vi.fn(async () => undefined),
  addObservation: vi.fn(async () => null),
  updateObservation: vi.fn(async () => undefined),
  clearMemory: vi.fn(async () => undefined),
}));

vi.mock("../../state/StudioContext", () => ({
  useStudio: () => studio,
}));

function observation(overrides: Partial<Observation> = {}): Observation {
  return {
    id: "o-1",
    kind: "career",
    text: "Wants to be known for fixing activation.",
    data: {},
    status: "suggested",
    confidence: 0.8,
    source_turn: 1,
    created_at: "2026-10-21T10:00:00+00:00",
    updated_at: "2026-10-21T10:00:00+00:00",
    ...overrides,
  };
}

describe("MemoryPanel", () => {
  beforeEach(() => {
    studio.memory = [];
    studio.memoryLoading = false;
    studio.refreshMemory.mockClear();
    studio.addObservation.mockClear();
    studio.updateObservation.mockClear();
    studio.clearMemory.mockClear();
  });

  it("shows what the agent learned, grouped and labelled", () => {
    studio.memory = [
      observation({ id: "o-1", status: "confirmed", text: "Accountable for activation." }),
      observation({ id: "o-2", kind: "constraint", text: "Enterprise approval may be slow." }),
    ];

    render(<MemoryPanel />);

    expect(screen.getByRole("heading", { name: "What I've learned" })).toBeInTheDocument();
    expect(screen.getByText("Accountable for activation.")).toBeInTheDocument();
    expect(screen.getByText("You confirmed this")).toBeInTheDocument();
    expect(screen.getByText("Still checking")).toBeInTheDocument();
    expect(screen.getByText("80% sure")).toBeInTheDocument();
  });

  it("confirms a suggestion", () => {
    studio.memory = [observation()];
    render(<MemoryPanel />);

    fireEvent.click(screen.getByRole("button", { name: "That's right" }));

    expect(studio.updateObservation).toHaveBeenCalledWith("o-1", { status: "confirmed" });
  });

  it("edits an observation in place", async () => {
    studio.memory = [observation()];
    render(<MemoryPanel />);

    fireEvent.click(screen.getByRole("button", { name: "Edit" }));
    fireEvent.change(screen.getByLabelText("Edit what I've learned"), {
      target: { value: "Wants to own onboarding activation." },
    });
    fireEvent.click(screen.getByRole("button", { name: "Save" }));

    await waitFor(() =>
      expect(studio.updateObservation).toHaveBeenCalledWith("o-1", {
        text: "Wants to own onboarding activation.",
      }),
    );
  });

  it("adds context in the PM's own words", async () => {
    render(<MemoryPanel />);

    fireEvent.change(screen.getByLabelText("What should I know?"), {
      target: { value: "I report to the VP of Growth." },
    });
    fireEvent.click(screen.getByRole("button", { name: "Add" }));

    await waitFor(() =>
      expect(studio.addObservation).toHaveBeenCalledWith({
        kind: "career",
        text: "I report to the VP of Growth.",
      }),
    );
  });

  it("asks before forgetting everything", () => {
    studio.memory = [observation()];
    render(<MemoryPanel />);

    fireEvent.click(screen.getByRole("button", { name: "Forget everything" }));
    expect(studio.clearMemory).not.toHaveBeenCalled();

    fireEvent.click(screen.getByRole("button", { name: "Yes, forget it all" }));
    expect(studio.clearMemory).toHaveBeenCalled();
  });
});

