-/**
- * Browser-side speech recognition — the cheapest transcription path.
- *
- * When the browser ships a recogniser, the audio never leaves the machine:
- * the recogniser runs in the browser and hands back text. It is not
- * universal though (Firefox has no implementation), so the studio falls back
- * to the sidecar, which transcribes a recording against the model backend.
- */
-
-import type { TranscriptionMode } from "../types";
-
-/** Which transcription path to use. */
-export type TranscriptionPath = "browser" | "server";
-
-/** Why browser speech recognition did not produce a transcript. */
-export type SpeechFailureReason = "unsupported" | "denied" | "no-speech" | "error";
-
-const SPEECH_MESSAGES: Record<SpeechFailureReason, string> = {
-  unsupported: "This browser has no speech recognition. The studio will transcribe a recording instead.",
-  denied: "Speech recognition was denied. The studio will transcribe a recording instead.",
-  "no-speech": "No speech was detected in that recording.",
-  error: "Speech recognition failed. The studio will transcribe a recording instead.",
-};
-
-/** The user-facing message for a speech failure. */
-export function describeSpeechFailure(reason: SpeechFailureReason): string {
-  return SPEECH_MESSAGES[reason];
-}
-
-/** Thrown when browser speech recognition does not produce a transcript. */
-export class SpeechError extends Error {
-  readonly reason: SpeechFailureReason;
-
-  constructor(reason: SpeechFailureReason) {
-    super(SPEECH_MESSAGES[reason]);
-    this.name = "SpeechError";
-    this.reason = reason;
-  }
-}
-
-function recognitionConstructor(): (new () => SpeechRecognition) | null {
-  if (typeof window === "undefined") {
-    return null;
-  }
-  const candidate =
-    window.SpeechRecognition ??
-    (window as unknown as { webkitSpeechRecognition?: typeof SpeechRecognition })
-      .webkitSpeechRecognition;
-  return candidate ?? null;
-}
-
-/** True when this browser ships a speech recogniser. */
-export function browserSpeechSupported(): boolean {
-  return recognitionConstructor() !== null;
-}
-
-/**
- * Choose a transcription path.
- *
- * "auto" prefers the browser recogniser when it exists, because it keeps the
- * audio on the machine. "browser" and "server" force one path.
- */
-export function choosePath(mode: TranscriptionMode): TranscriptionPath {
-  if (mode === "browser") {
-    return "browser";
-  }
-  if (mode === "server") {
-    return "server";
-  }
-  return browserSpeechSupported() ? "browser" : "server";
-}
-
-/**
- * Listen once and return what was said.
- *
- * @param lang Optional BCP-47 language tag. Omitted means auto-detect.
- * @throws SpeechError when there is no recogniser, the user denied it, the
- * recogniser failed, or it heard nothing.
- */
-export function transcribeWithBrowserSpeech(lang?: string): Promise<string> {
-  const Recognition = recognitionConstructor();
-  if (!Recognition) {
-    return Promise.reject(new SpeechError("unsupported"));
-  }
-
-  return new Promise<string>((resolve, reject) => {
-    const recognition = new Recognition();
-    recognition.continuous = false;
-    recognition.interimResults = false;
-    if (lang) {
-      recognition.lang = lang;
-    }
-
-    let settled = false;
-    let transcript = "";
-
-    const finish = (action: () => void) => {
-      if (settled) {
-        return;
-      }
-      settled = true;
-      action();
-    };
-
-    recognition.onresult = (event: SpeechRecognitionEvent) => {
-      for (let index = event.resultIndex; index < event.results.length; index += 1) {
-        const result = event.results[index];
-        if (result.isFinal) {
-          transcript += result[0]?.transcript ?? "";
-        }
-      }
-    };
-
-    recognition.onerror = (event: SpeechRecognitionErrorEvent) => {
-      const denied = event.error === "not-allowed" || event.error === "service-not-allowed";
-      finish(() => reject(new SpeechError(denied ? "denied" : "error")));
-    };
-
-    recognition.onend = () => {
-      const text = transcript.trim();
-      finish(() =>
-        text ? resolve(text) : reject(new SpeechError("no-speech")),
-      );
-    };
-
-    try {
-      recognition.start();
-    } catch {
-      finish(() => reject(new SpeechError("error")));
-    }
-  });
-}

