Now router.py: import memory errors/schemas, add routes, pass memory to stream_chat.

Add imports:
```python
from agentic_odi_studio_api.studio.memory import ObservationNotFoundError
from ...schemas import (ObservationCreateRequest, ObservationModel, ObservationResponse, ObservationListResponse, ObservationUpdateRequest, ConversationResponse, LatestConversationResponse, ConversationModel, TurnModel)
```

Routes:
```python
def _memory(request): return request.app.state.memory

@router.get("/memory/observations", response_model=ObservationListResponse)
def list_memory(request): 
    return {"observations": [o.to_dict() for o in _memory(request).list_observations()]}

@router.post("/memory/observations", response_model=ObservationResponse)
def add_memory(body, request):
    try:
        obs = _memory(request).add_observation(kind=body.kind, text=body.text, data=body.data, status="confirmed" if body.confirmed else "suggested", confidence=body.confidence)
    except ValueError as exc: raise HTTPException(422, detail=str(exc))
    return {"observation": obs.to_dict()}

@router.patch("/memory/observations/{observation_id}", response_model=ObservationResponse)
def patch_memory(...):
    try: obs = update(...)
    except ObservationNotFoundError: 404
    except ValueError: 422

@router.delete("/memory/observations/{id}")
def delete_memory(...):
    try: ...
    except ObservationNotFoundError: 404
    return {"ok": True}

@router.delete("/memory")
def clear_memory(request): _memory(request).clear_memory(); return {"ok": True}

@router.get("/conversations/latest", response_model=LatestConversationResponse)
def latest_conversation(request):
    memory = _memory(request)
    conversation = memory.latest_conversation()
    if conversation is None: return {"conversation": None, "turns": []}
    return {"conversation": conversation.to_dict(), "turns": [t.to_dict() for t in memory.list_turns(conversation.id)]}

@router.post("/conversations", response_model=ConversationResponse)
def create_conversation(request): return {"conversation": _memory(request).create_conversation().to_dict()}
