  finally { setMemoryLoading(false); }
}, []);

const addObservation = useCallback(async (payload: AddObservationPayload) => {
  try { const obs = await apiAddObservation(payload); setMemory(prev => [...prev, obs]); return obs; } catch { pushToast("error", "Could not save that context."); return null; }
