export const SIDECAR_ORIGIN = "http://127.0.0.1:8100";

interface TauriWindow {
  __TAURI_INTERNALS__?: unknown;
}

export function isTauri(): boolean {
  return typeof window !== "undefined" && "__TAURI_INTERNALS__" in (window as TauriWindow);
}

export function resolveApiBase(tauri: boolean): string {
  return tauri ? SIDECAR_ORIGIN : "";
}

export function apiUrl(path: string): string {
  return `${resolveApiBase(isTauri())}${path}`;
}
import "@testing-library/jest-dom/vitest";

// Node exposes an experimental localStorage global that shadows jsdom's and
// lacks clear/removeItem. Replace it with a small deterministic store so the
// app and the tests share one working implementation.
class MemoryStorage implements Storage {
  private readonly store = new Map<string, string>();

  get length(): number {
    return this.store.size;
  }

  clear(): void {
    this.store.clear();
  }

  getItem(key: string): string | null {
    return this.store.has(key) ? (this.store.get(key) as string) : null;
  }

  key(index: number): string | null {
    return Array.from(this.store.keys())[index] ?? null;
  }

  removeItem(key: string): void {
    this.store.delete(key);
  }

  setItem(key: string, value: string): void {
    this.store.set(key, String(value));
  }
}

Object.defineProperty(globalThis, "localStorage", {
  value: new MemoryStorage(),
  configurable: true,
});

