+            <div className="setup__replies" aria-label="Suggested answers">
+              {replies.map((reply) => (
+                <button
+                  key={reply.label}
+                  type="button"
+                  className={`suggestion${reply.primary ? " suggestion--primary" : ""}${
+                    reply.quiet ? " suggestion--quiet" : ""
+                  }`}
+                  onClick={reply.run}
+                >
+                  {reply.label}
+                </button>
+              ))}
+            </div>
+          )}
+        </div>
+      </div>
+
+      <div className="chat__dock">
+        <Composer
+          value={input}
+          onChange={setInput}
+          onSubmit={() => {
+            const value = input;
+            setInput("");
+            answer(value);
+          }}
+          onCommand={handleCommand}
+          streaming={false}
+          onStop={() => undefined}
+          inputRef={inputRef}
+          autoFocus
+          placeholder={placeholder}
+        />
+      </div>
+    </section>
+  );
+}

