+}
+
+.connection-list li:hover {
+  background: var(--surface);
+}
+
+.connection-list__value {
+  margin-left: auto;
+  color: var(--faint);
+  font-size: 0.7rem;
+}
+
+.settings__actions {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 7px;
+}
+
+.muted {
+  color: var(--faint);
+  font-size: 0.72rem;
+}
+
+/* ------------------------------------------------------------------ */
+/* Toasts                                                             */
+/* ------------------------------------------------------------------ */
+.toast-stack {
+  position: fixed;
+  right: 18px;
+  bottom: 18px;
+  z-index: 1000;
+  display: flex;
+  flex-direction: column;
+  gap: 8px;
+  max-width: 360px;
+}
+
+.toast {
+  display: flex;
+  align-items: flex-start;
+  justify-content: space-between;
+  gap: 10px;
+  padding: 10px 12px;
+  border: 1px solid var(--line-strong);
+  border-radius: 11px;
+  background: rgba(16, 18, 23, 0.96);
+  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.45);
+  color: var(--text);
+  font-size: 0.8rem;
+}
+
+.toast--success {
+  border-color: rgba(74, 222, 128, 0.4);
+}
+
+.toast--error {
+  border-color: rgba(248, 113, 113, 0.4);
+}
+
+.toast--info {
+  border-color: rgba(139, 140, 248, 0.4);
+}
+
+.toast button {
+  border: 0;
+  background: transparent;
+  color: var(--faint);
+  font-size: 0.9rem;
+  cursor: pointer;
+}
+
+/* ------------------------------------------------------------------ */
+/* Error fallback                                                     */
+/* ------------------------------------------------------------------ */
+.error-page {
+  display: grid;
+  place-items: center;
+  min-height: 100dvh;
+  padding: 24px;
+  background: var(--bg);
+}
+
+.error-page__card {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 12px;
+  max-width: 440px;
+  text-align: center;
+}
+
+.error-page__title {
+  margin: 0;
+  font-size: clamp(1.3rem, 3vw, 1.7rem);
+  font-weight: 600;
+  letter-spacing: -0.02em;
+  line-height: 1.25;
+}
+
+/* ------------------------------------------------------------------ */
+/* Loading + motion                                                   */
+/* ------------------------------------------------------------------ */
+.skeleton {
+  border-radius: 8px;
+  background: linear-gradient(
+    90deg,
+    rgba(255, 255, 255, 0.03) 25%,
+    rgba(255, 255, 255, 0.08) 50%,
+    rgba(255, 255, 255, 0.03) 75%
+  );
+  background-size: 200% 100%;
+  animation: shimmer 1.6s infinite ease-in-out;
+}
+
+.skeleton--tile {
+  height: 58px;
+}
+
+.skeleton--line {
+  height: 12px;
+  margin-bottom: 8px;
+}
+
+@keyframes shimmer {
+  0% {
+    background-position: -200% 0;
+  }
+  100% {
+    background-position: 200% 0;
+  }
+}
+
+@keyframes hero-in {
+  from {
+    opacity: 0;
+    transform: translateY(6px);
+    filter: blur(2px);
+  }
+  to {
+    opacity: 1;
+    transform: translateY(0);
+    filter: blur(0);
+  }
+}
+
+/* ------------------------------------------------------------------ */
+/* Offline                                                            */
+/* ------------------------------------------------------------------ */
+.offline {
+  display: flex;
+  flex: none;
+  flex-wrap: wrap;
+  align-items: center;
+  justify-content: space-between;
+  gap: 10px 16px;
+  margin: 6px 22px 0;
+  padding: 10px 14px;
+  border: 1px solid rgba(245, 158, 11, 0.24);
+  border-radius: 12px;
+  background: rgba(245, 158, 11, 0.06);
+  color: var(--muted);
+  font-size: 0.78rem;
+  line-height: 1.45;
+}
+
+.offline__text strong {
+  color: var(--text);
+}
+
+.offline__actions {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 6px;
+}
+
+/* ------------------------------------------------------------------ */
+/* Transcript notices and tags                                        */
+/* ------------------------------------------------------------------ */
+.message--notice {
+  display: block;
+  padding: 12px 16px;
+  border: 1px solid var(--line);
+  border-radius: 12px;
+  background: rgba(99, 102, 241, 0.055);
+  font-size: 0.84rem;
+}
+
+.message--notice .markdown p:first-child {
+  margin-top: 0;
+}
+
+.message--notice .markdown p:last-child {
+  margin-bottom: 0;
+}
+
+.message__tag {
+  display: inline-block;
+  margin-bottom: 6px;
+  padding: 2px 7px;
+  border: 1px solid rgba(245, 158, 11, 0.3);
+  border-radius: 999px;
+  color: #f0b45a;
+  font-size: 0.62rem;
+  font-weight: 600;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+}
+
+/* ------------------------------------------------------------------ */
+/* Setup conversation                                                 */
+/* ------------------------------------------------------------------ */
+.chat--setup .chat__scroll {
+  padding-top: 10px;
+}
+
+.setup {
+  display: flex;
+  flex-direction: column;
+  gap: 16px;
+  padding-top: 4px;
+}
+
+.setup__meta {
+  display: flex;
+  flex: none;
+  align-items: center;
+  justify-content: space-between;
+  gap: 12px;
+  width: calc(100% - 44px);
+  max-width: 720px;
+  margin: 6px auto 0;
+  color: var(--faint);
+  font-size: 0.7rem;
+}
+
+.setup__turns {
+  display: flex;
+  flex-direction: column;
+  gap: 16px;
+}
+
+.setup__replies {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 6px;
+  margin-left: 38px;
+  padding-bottom: 4px;
+  animation: fade-in 0.3s ease;
+}
+
+.suggestion--primary {
+  border-color: rgba(139, 140, 248, 0.5);
+  background: rgba(99, 102, 241, 0.16);
+  color: var(--text);
+}
+
+
+
+/* ------------------------------------------------------------------ */
+/* Manual data controls                                               */
+/* ------------------------------------------------------------------ */
+.step__name {
+  flex: 1;
+  min-width: 0;
+}
+
+.step__actions {
+  display: flex;
+  gap: 2px;
+  margin-left: auto;
+  opacity: 0;
+  transition: opacity 0.14s ease;
+}
+
+.step:hover .step__actions,
+.step:focus-within .step__actions {
+  opacity: 1;
+}
+
+.step__edit {
+  display: flex;
+  flex: 1;
+  align-items: center;
+  gap: 6px;
+}
+
+.input--order {
+  width: 68px;
+  flex: none;
+}
+
+.input--area {
+  min-height: 84px;
+  padding: 9px 11px;
+  line-height: 1.5;
+  resize: vertical;
+}
+
+.button--danger {
+  border-color: rgba(239, 68, 68, 0.35);
+  background: rgba(239, 68, 68, 0.12);
+}
+
+.button--danger:hover:not(:disabled) {
+  background: rgba(239, 68, 68, 0.2);
+}
+
+.quiet-action--danger:hover {
+  color: #fca5a5;
+}
+
+.suggestion--quiet {
+  border-style: dashed;
+  color: var(--faint);
+}
+
+.card__edit {
+  display: grid;
+  gap: 10px;
+  padding: 12px;
+  border: 1px solid var(--line);
+  border-radius: 10px;
+  background: rgba(255, 255, 255, 0.02);
+}
+
+.card__slider {
+  display: grid;
+  gap: 6px;
+  color: var(--muted);
+  font-size: 0.74rem;
+}
+
+.card__edit-actions {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+}
+
+.settings__context {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 14px;
+  padding: 12px 14px;
+  border: 1px solid var(--line);
+  border-radius: 12px;
+  background: rgba(99, 102, 241, 0.06);
+}
+
+.settings__context-label {
+  margin: 0 0 3px;
+  color: var(--faint);
+  font-size: 0.64rem;
+  font-weight: 600;
+  letter-spacing: 0.09em;
+  text-transform: uppercase;
+}
+
+.settings__context-value {
+  margin: 0;
+  color: var(--muted);
+  font-size: 0.8rem;
+  line-height: 1.45;
+}
+
+/* ------------------------------------------------------------------ */
+/* Bell & Notification Badges                                         */
+/* ------------------------------------------------------------------ */
+
+.bell-badge {
+  position: absolute;
+  top: -2px;
+  right: -2px;
+  display: grid;
+  place-items: center;
+  min-width: 16px;
+  height: 16px;
+  padding: 0 4px;
+  border-radius: 999px;
+  background: var(--accent-strong);
+  color: #ffffff;
+  font-size: 0.62rem;
+  font-weight: 700;
+  box-shadow: 0 0 8px rgba(99, 102, 241, 0.6);
+  animation: pulse-badge 2s infinite ease-in-out;
+}
+
+@keyframes pulse-badge {
+  0%, 100% {
+    transform: scale(1);
+    box-shadow: 0 0 6px rgba(99, 102, 241, 0.5);
+  }
+  50% {
+    transform: scale(1.1);
+    box-shadow: 0 0 12px rgba(139, 140, 248, 0.8);
+  }
+}
+
+.catchup-feed {
+  animation: fade-in 0.25s cubic-bezier(0.16, 1, 0.3, 1);
+}
+
+.catchup-summary {
+  background: linear-gradient(135deg, rgba(99, 102, 241, 0.08) 0%, rgba(255, 255, 255, 0.01) 100%);
+  border-color: rgba(139, 140, 248, 0.25);
+  backdrop-filter: blur(12px);
+}
+
+.catchup-summary__actions {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+}
+
+.catchup-card {
+  position: relative;
+  transition: all 0.2s ease-in-out;
+}
+
+.catchup-card:hover {
+  transform: translateY(-1px);
+  border-color: var(--line-strong);
+  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.3);
+}
+
+.catchup-card.is-unread {
+  border-left: 3px solid var(--accent);
+  background: rgba(99, 102, 241, 0.04);
+}
+
+@media (max-width: 1023px) {
+  .lens {
+    position: fixed;
+    inset: 0;
+    z-index: 60;
+    width: 100%;
+    max-width: none;
+    border-left: 0;
+    background: var(--bg);
+    box-shadow: none;
+  }
+
+  .lens__head {
+    padding: 14px 16px;
+  }
+
+  .lens__body {
+    padding: 18px 16px 32px;
+  }
+
+  .rail {
+    padding-inline: 18px;
+  }
+
+  .setup__meta {
+    width: calc(100% - 36px);
+  }
+
+  .setup__replies {
+    margin-left: 0;
+  }
+
+  .offline {
+    margin-inline: 14px;
+  }
+
+  .chat__welcome {
+    padding: 12px 18px 40px;
+  }
+
+  .chat__scroll {
+    padding-inline: 18px;
+  }
+
+  .chat__dock {
+    padding-inline: 12px;
+  }
+
+  .composer__hint span:first-child {
+    display: none;
+  }
+
+  .composer__status {
+    max-width: 100%;
+  }
+
+  .before-after {
+    grid-template-columns: 1fr;
+  }
+}
+
+@media (hover: none) {
+  .message__actions {
+    opacity: 1;
+  }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  *,
+  *::before,
+  *::after {
+    animation-duration: 0.001ms !important;
+    animation-iteration-count: 1 !important;
+    transition-duration: 0.001ms !important;
+  }
+}
+
+/* ------------------------------------------------------------------ */
+/* Apple-inspired polish & Glassmorphism refinements                   */
+/* ------------------------------------------------------------------ */
+
+.outcome-card {
+  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.2s cubic-bezier(0.16, 1, 0.3, 1);
+  background: var(--studio-surface);
+  border: 1px solid var(--studio-border);
+  border-radius: var(--studio-radius);
+  padding: 16px;
+  backdrop-filter: blur(12px);
+}
+
+.outcome-card:hover {
+  transform: translateY(-2px);
+  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4), 0 0 1px rgba(255, 255, 255, 0.2);
+  border-color: rgba(255, 255, 255, 0.16);
+}
+
+.pulsing-card {
+  box-shadow: 0 0 20px rgba(251, 191, 36, 0.15);
+  border-color: rgba(251, 191, 36, 0.3);
+}
+
+.studio-button {
+  transition: all 0.15s ease-in-out;
+  font-weight: 500;
+  letter-spacing: -0.01em;
+}
+
+.studio-button:hover:not(:disabled) {
+  transform: scale(1.02);
+  opacity: 0.95;
+}
+
+.studio-button:active:not(:disabled) {
+  transform: scale(0.98);
+}
+
+.studio-button--primary {
+  background: linear-gradient(135deg, var(--studio-indigo) 0%, var(--studio-indigo-strong) 100%);
+  color: #ffffff;
+  box-shadow: 0 2px 8px rgba(99, 102, 241, 0.3);
+}
+
+.studio-metric {
+  background: rgba(255, 255, 255, 0.02);
+  border: 1px solid var(--studio-border);
+  border-radius: 10px;
+  padding: 14px;
+  backdrop-filter: blur(8px);
+}
+
+/* Custom scrollbar for data density tables */
+::-webkit-scrollbar {
+  width: 8px;
+  height: 8px;
+}
+
+::-webkit-scrollbar-track {
+  background: rgba(0, 0, 0, 0.2);
+}
+
+::-webkit-scrollbar-thumb {
+  background: rgba(255, 255, 255, 0.15);
+  border-radius: 4px;
+}
+
+::-webkit-scrollbar-thumb:hover {
+  background: rgba(255, 255, 255, 0.3);
+}
+
+/* ------------------------------------------------------------------ */
+/* Agent-composed surfaces                                            */
+/* ------------------------------------------------------------------ */
+.ui-code {
+  font-family: var(--mono);
+  font-size: 0.86em;
+  background: rgba(148, 163, 184, 0.14);
+  padding: 1px 5px;
+  border-radius: 4px;
+}
+
+/* ------------------------------------------------------------------ */
+/* Generated surfaces                                                 */
+/* ------------------------------------------------------------------ */
+.ui-surface {
+  animation: surface-enter 0.28s cubic-bezier(0.16, 1, 0.3, 1) both;
+  min-width: 0;
+}
+
+@keyframes surface-enter {
+  from {
+    opacity: 0;
+    transform: translateY(6px);
+  }
+
+  to {
+    opacity: 1;
+    transform: none;
+  }
+}
+
+.ui-stack {
+  display: flex;
+  flex-direction: column;
+  min-width: 0;
+}
+
+.ui-stack--horizontal {
+  flex-direction: row;
+  flex-wrap: wrap;
+  align-items: center;
+  justify-content: flex-start;
+}
+
+.ui-grid {
+  display: grid;
+  min-width: 0;
+}
+
+.ui-grid--2 {
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+}
+
+.ui-grid--3 {
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+}
+
+.ui-gap--sm {
+  gap: 8px;
+}
+
+.ui-gap--md {
+  gap: 12px;
+}
+
+.ui-gap--lg {
+  gap: 18px;
+}
+
+.ui-heading {
+  margin: 0;
+  font-size: 0.95rem;
+}
+
+.ui-text {
+  font-size: 0.92rem;
+  line-height: 1.55;
+}
+
+.ui-text--muted {
+  color: var(--studio-muted);
+}
+
+.ui-text--positive {
+  color: var(--studio-green);
+}
+
+.ui-text--warning {
+  color: var(--studio-amber);
+}
+
+.ui-text--critical {
+  color: var(--studio-red);
+}
+
+.ui-caption {
+  margin: 0;
+  font-size: 0.72rem;
+  letter-spacing: 0.06em;
+  text-transform: uppercase;
+  color: var(--studio-muted);
+}
+
+/* Cards */
+.ui-card {
+  display: flex;
+  flex-direction: column;
+  gap: 12px;
+  padding: 16px 18px;
+  border-radius: 14px;
+  border: 1px solid var(--studio-border);
+  background: linear-gradient(180deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0.015));
+  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.04) inset, 0 12px 30px -26px rgba(0, 0, 0, 0.9);
+  min-width: 0;
+}
+
+.ui-card--urgent {
+  border-color: rgba(251, 191, 36, 0.28);
+  box-shadow: 0 0 0 1px rgba(251, 191, 36, 0.05), 0 18px 44px -30px rgba(251, 191, 36, 0.45);
+}
+
+.ui-card--unknown {
+  background: transparent;
+  border-style: dashed;
+  gap: 4px;
+}
+
+.ui-card__head {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 10px;
+}
+
+.ui-card__id {
+  font-size: 0.72rem;
+  font-weight: 700;
+  letter-spacing: 0.09em;
+  text-transform: uppercase;
+  color: var(--studio-indigo);
+}
+
+.ui-card__statement {
+  margin: 0;
+  font-size: 0.98rem;
+  font-weight: 500;
+  line-height: 1.45;
+}
+
+.ui-card__title {
+  margin: 0;
+  font-size: 1rem;
+}
+
+.ui-card__formula {
+  margin: 0;
+  font-size: 0.72rem;
+  color: var(--studio-muted);
+  font-variant-numeric: tabular-nums;
+}
+
+.ui-card__meters {
+  display: grid;
+  gap: 8px;
+}
+
+.ui-card__evidence {
+  margin: 0;
+  padding: 10px 12px;
+  border-left: 2px solid rgba(129, 140, 248, 0.5);
+  background: rgba(15, 23, 42, 0.5);
+  border-radius: 0 8px 8px 0;
+  font-size: 0.84rem;
+  color: #cbd5e1;
+}
+
+/* Pills */
+.ui-pill {
+  display: inline-flex;
+  align-items: center;
+  padding: 3px 9px;
+  border-radius: 9999px;
+  border: 1px solid transparent;
+  font-size: 0.72rem;
+  font-weight: 600;
+  white-space: nowrap;
+  font-variant-numeric: tabular-nums;
